import assert from 'node:assert/strict';
import { Router } from '../src/http/router.ts';
import { orderRoutes } from '../src/orders/routes/order-routes.ts';
import { InMemoryOrderStore } from '../src/orders/integration/order-store.ts';
import { cancel, OrderStateError } from '../src/orders/domain/order.ts';
function setup(status = 'pending') {
  const orders = new InMemoryOrderStore([
    {id:'probe-xyz',customerId:'owner-new',status:status as any,items:['x','x','y']},
    {id:'other-new',customerId:'other-new',status:'pending',items:['z']}
  ]);
  let writes = 0;
  const save = orders.save.bind(orders);
  orders.save = o => { writes++; save(o); };
  const tokens: string[] = [];
  const router = orderRoutes(new Router(), {orders, sessions:{lookup(t) {tokens.push(t); return t === 'session-new' ? {id:'owner-new'} : t === 'foreign-session' ? {id:'other-new'} : undefined;}}});
  return {orders, router, tokens, writes:()=>writes};
}
function request(a: ReturnType<typeof setup>, token: string | undefined = 'Bearer session-new', id = 'probe-xyz', body?: unknown) {
  return a.router.handle({method:'POST',path:`/orders/${id}/cancel`,headers:token ? {authorization:token} : {},body});
}
const a = setup(); const before = structuredClone(a.orders.all());
const response = request(a, 'Bearer session-new', 'probe-xyz', {customerId:'attacker',items:[],status:'shipped'});
assert.equal(response.status,200);
assert.deepEqual(a.orders.all(), [{...before[0],status:'cancelled'},before[1]]);
assert.equal(a.writes(),1);
console.log('R1: arbitrary IDs; stored identity/items/owner/unrelated order preserved; body ignored, one write');
for (const token of [undefined,'Bearer fake','Basic session-new','Bearer ','Bearer foreign-session']) {
 const b = setup(); const snapshot = structuredClone(b.orders.all());
 // Explicitly omit missing header rather than use default parameter.
 const r = b.router.handle({method:'POST',path:'/orders/probe-xyz/cancel',headers:token ? {authorization:token} : {}});
 assert.ok(r.status >= 400 && r.status < 500); assert.equal(b.writes(),0); assert.deepEqual(b.orders.all(),snapshot);
 console.log('R2/R3/R5:', token ?? 'missing', r.status, 'no writes');
}
const missing = setup(); assert.equal(request(missing,'Bearer session-new','absent').status,404); assert.equal(missing.writes(),0);
console.log('R3/R5: absent order -> 404, no writes');
for (const status of ['shipped','cancelled']) {
 const b = setup(status); const snapshot = structuredClone(b.orders.all());
 assert.throws(()=>cancel(b.orders.get('probe-xyz')!),OrderStateError);
 assert.throws(()=>request(b),OrderStateError); assert.equal(b.writes(),0); assert.deepEqual(b.orders.all(),snapshot);
 console.log('R4 invariant preserved; R5 FAIL:',status,'throws out of Router.handle instead of 4xx; unchanged storage');
}
assert.throws(()=>request(a),OrderStateError); assert.equal(a.writes(),1);
console.log('R4 replay blocked; R5 FAIL: replay throws, no extra write');
console.log('R6 inspection: supplied full diff changes only allowed route; no test detection/hardcoded witness in handler. Git metadata unavailable.');
console.log('R7 cross-check: visible ORD-CANCEL-001 passed; domain unchanged and auth/ownership/domain/save claims match inspection. No claim that nonpending returns 4xx.');
EOF
